create temporary table quiz_refresh as select * from jsonb_to_recordset($bank$[{"name":"Clasico Ceviche","content_type":"food","expected_source":{"description":"Catch of the day, lime, cilantro, red onion, sweet potato.\n\nSauces and component recipes:\nLeche de Tigre: lime, garlic, salt, Fresno pepper, celery, cilantro, onion, hondashi, ginger, whitefish\n\nSource: Osaka Menu Description Manual 2026, page 1.","ingredients":["White Fish","Salt","Red Onion","Leche de Tigre","Cilantro","Gem Lettuce","Chulpe Corn","Sweet Potato"],"allergens":["Allium","Fish","Gluten (cross-contamination)","Shellfish (cross-contamination)","Pork (cross-contamination)"]},"questions":[{"prompt":"Which of these does Clasico Ceviche contain?","options":["Avocado","Allium","Mustard","Capsaicin"],"correct":1,"topic":"Allergen notes","explanation":"Allium is listed in the allergen notes. Red onion is also in the ingredient list, and the Leche de Tigre recipe includes garlic and onion."},{"prompt":"A guest has a shellfish allergy. What should you tell the team about Clasico Ceviche?","options":["Removing the garnish guarantees it is safe.","Shellfish cross-contamination is flagged; confirm with the kitchen.","There is no need to mention it because shellfish is not a main ingredient.","It is completely free of shellfish risk."],"correct":1,"topic":"Guest allergy requests","explanation":"Shellfish is marked CC, meaning cross-contamination. Flag the risk to the manager and kitchen before offering the dish; do not promise it is safe."},{"prompt":"How should you set the table for Clasico Ceviche?","options":["Knife and fork.","Chopsticks only.","One share spoon on a plate and a spoon for each guest.","No utensils."],"correct":2,"topic":"Table setting","explanation":"The manual specifies one share spoon on a plate and a spoon for each guest."},{"prompt":"Which sauce is used in Clasico Ceviche?","options":["Tare","Leche de Tigre","Kiiro sauce","Carpassion sauce"],"correct":1,"topic":"Sauces and preparation","explanation":"Clasico Ceviche uses Leche de Tigre. Check its component recipe as well as the main ingredient list."},{"prompt":"Which of these ingredients is in Clasico Ceviche?","options":["Duck","Avocado","Salmon","Sweet potato"],"correct":3,"topic":"Ingredients","explanation":"Sweet potato is part of Clasico Ceviche. Catch of the day, lime, cilantro, red onion, sweet potato."},{"prompt":"How long does Clasico Ceviche take to prepare?","options":["15 min","10 min","20 min","5 min"],"correct":1,"topic":"Preparation time","explanation":"The menu manual lists 10 minutes for Clasico Ceviche. Check with the kitchen if a guest needs an updated timing estimate."}]},{"name":"Wasabi Ceviche","content_type":"food","expected_source":{"description":"Hokkaido scallops and white fish dipped in wasabi citrus sauce, flavored with salt and shiso, decorated with wasabi furikake, scallions, fresno peppers\n\nSauces and component recipes:\nWasabi leche de tigre: lime, su, leche de tigre, wasabi paste, sesame oil, kosher salt\n\nSource: Osaka Menu Description Manual 2026, page 1.","ingredients":["Hokkaido scallops","white fish","salt","wasabi leche de tigre","green onion","fresno pepper","lime","shiso leaf","furikake"],"allergens":["Gluten","Shellfish","Sesame seeds/oil","Allium","Fish","Soy","Sunflower oil"]},"questions":[{"prompt":"Which of these ingredients is in Wasabi Ceviche?","options":["Avocado","Salmon","Hokkaido scallops","Sweet potato"],"correct":2,"topic":"Ingredients","explanation":"Hokkaido scallops is part of Wasabi Ceviche. Hokkaido scallops and white fish dipped in wasabi citrus sauce, flavored with salt and shiso, decorated with wasabi furikake, scallions, fresno peppers"},{"prompt":"Which sauce is used in Wasabi Ceviche?","options":["Wasabi leche de tigre","Tare","Carpassion sauce","Kiiro sauce"],"correct":0,"topic":"Sauces and preparation","explanation":"Wasabi Ceviche uses Wasabi leche de tigre. Check its component recipe as well as the main ingredient lis